{
  "meta": {
    "name": "Public Notes",
    "description": "A public notes app where anyone can view notes, but only admins can edit them, with role-based permissions."
  },
  "entities": [
    {
      "name": "Note",
      "fields": [
        {
          "name": "title",
          "type": "string",
          "required": true
        },
        {
          "name": "content",
          "type": "text",
          "required": true
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "admin",
      "description": "Can create, read, update, and delete notes."
    },
    {
      "name": "viewer",
      "description": "Can only read notes.",
      "isDefault": true
    }
  ],
  "permissions": [
    {
      "role": "viewer",
      "entity": "Note",
      "actions": [
        "read"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Note",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    }
  ],
  "pages": [
    {
      "name": "Notes List",
      "route": "/notes",
      "type": "list",
      "entity": "Note",
      "access": [
        "viewer",
        "admin"
      ]
    },
    {
      "name": "Note Detail",
      "route": "/notes/:id",
      "type": "detail",
      "entity": "Note",
      "access": [
        "viewer",
        "admin"
      ]
    },
    {
      "name": "New Note",
      "route": "/notes/new",
      "type": "form",
      "entity": "Note",
      "access": [
        "admin"
      ]
    },
    {
      "name": "Edit Note",
      "route": "/notes/:id/edit",
      "type": "form",
      "entity": "Note",
      "access": [
        "admin"
      ]
    }
  ],
  "businessRules": [],
  "auth": {
    "strategy": "none",
    "requireAuth": false
  }
}
